middlewares.handlerTsCode:
(line: Message): Message | void => {
    if (line && line.content) {
        const text = line.content;

        // Initialize style object if it doesn't exist
        line.style = line.style || {};

        // --- HIGH PRIORITY MATCHES ---

        // Command (high priority) - White text, strong reddish background (multitail 203)
        if (/.*Command.*Failed.*/.test(text)) {
            line.style = { "color": "#ffffff", "background": "#ff5f5f", "font-weight": "bold" };
        } 
        // Command Send - Light sky blue text (multitail 111)
        else if (/.*(Command Send).*/.test(text)) {
            line.style = { "color": "#87afff" };
        } 
        // MQTT messages — Light Green text (multitail 120)
        else if (/.*MQTT.*/.test(text)) {
            line.style = { "color": "#87ff87" };
        } 
        // System-level messages - Green text on Red background
        else if (/.*_SYSTEM_.*/.test(text)) {
            line.style = { "color": "#00ff00", "background": "#ff0000" };
        } 
        // Demand — Warm orange text (multitail 216)
        else if (/.*_demand.*/.test(text)) {
            line.style = { "color": "#ffaf87" };
        } 

        // --- CONTEXTUAL TEMPERATURE / DHW MATCHES ---

        // Temperature & DHW (override RP/W/I base colors but NOT RQ) - Pale sand text (multitail 187)
        else if (/.*\|\s*(RP|W|I)\s*\|.*(temperature|dhw_temp|dhw_mode).*/.test(text)) {
            line.style = { "color": "#d7d7af" };
        } 

        // --- RF PROTOCOL VERBS FALLBACKS ---

        // Information frames (I) - Soft light blue text (multitail 153)
        else if (/.*\|\s*I\s*\|.*/.test(text)) {
            line.style = { "color": "#afffff" };
        } 
        // Requests (RQ) — Light Black / Dark Gray text (multitail 248)
        else if (/.*\|\s*RQ\s*\|.*/.test(text)) {
            line.style = { "color": "#a8a8a8" };
        } 
        // Replies (RP) — Bold White text
        else if (/.*\|\s*RP\s*\|.*/.test(text)) {
            line.style = { "color": "#ffffff", "font-weight": "bold" };
        } 
        // Writes (W) — Bold Light Magenta text (multitail 213)
        else if (/.*\|\s*W\s*\|.*/.test(text)) {
            line.style = { "color": "#ff87ff", "font-weight": "bold" };
        }
    }

    return line;
}

// 2026-06-18 22:30:45 |   | |   |                    | Opentherm Bridge   |  I | opentherm_sync   |  00  || {'ticker': 962}
// 2026-06-18 22:30:59 |   | |01 | Controller         | Opentherm Bridge   | RQ | actuator_state   |  00  || {}
// 2026-06-18 22:30:59 |   | |10 | Opentherm Bridge   | Controller         | RP | actuator_state   |  00  || {'modulation_level': 0.0, '_flags_2': '10', '_flags_3': [0, 0, 0, 0, 0, 0, 0, 0], 'ch_active': False, 'dhw_active': False, 'cool_active': False, 'flame_on': False, '_unknown_4': '00', '_unknown_5': 'FF'}
// 2026-06-18 22:34:16 |   | MQTT message received: {'command': 'get_system_time'}
// 2026-06-18 22:34:16 |   | Command Send Status: Transmitted (command=get_system_time)
// 2026-06-18 22:34:16 |   | |18 | evogateway         | Controller         | RQ | datetime         |  00  || {}
// 2026-06-18 22:34:16 |   | Command Send Status: Successful (command=get_system_time)
// 2026-06-18 22:34:16 |   | |01 | Controller         | evogateway         | RP | datetime         |  00  || {'datetime': '2026-06-18T22:34:21', 'is_dst': True, '_unknown_0': 'FC'}
// 2026-06-19 20:32:23 |   | evoGateway 4.6.1 (ramses_rf 0.57.1) starting
(line: Message): Message | void => {
    if (!line || !line.content) return line;

    let text = line.content.trim();

    if (text.startsWith("⬤")) {
        text = text.substring(1).trim();
    }

    const DEVICE_TYPES = { "01": "CTL", "02": "UFH", "04": "TRV", "07": "DHW", "10": "OTB", "13": "RLY", "18": "HGI", "34": "THM" };

    // Protocol rows always have || followed by a JSON object { or array [.
    // Previously only matched {, which caused array-payload rows (e.g. temperature)
    // to fall through to the system-message branch and dump the whole line into function.
    if (/\|\|\s*[{[]/.test(text)) {
        const doubleBar = text.indexOf("||");
        const metaSection = text.substring(0, doubleBar);
        const payloadSection = text.substring(doubleBar + 2).trim() || "{}";

        const cols = metaSection.split("|").map(c => c.trim()).filter(c => c !== "");

        line["time"] = cols[0] || "";
        const sourceType = cols[1] || "";
        line["sourceType"] = DEVICE_TYPES[sourceType] || sourceType;
        line["from"] = cols[2] || "";
        line["to"] = cols[3] || "";
        line["verb"] = cols[4] || "";
        line["function"] = cols[5] || "";
        line["zone"] = cols[6] || "";

        // I-type rows have no sourceType or from-device; empty cols filter away leaving only 5.
        // Must check cols.length alone — the old condition (verb === "") never fired because
        // the initial mapping puts "00" (zone) into verb for these rows, which is not empty.
        if (cols.length === 5) {
            const DEVICE_NAMES: Record<string, string> = {
                "Opentherm Bridge": "OTB", "Controller": "CTL", "evogateway": "HGI"
            };
            const toDevice = cols[1] || "";
            line["sourceType"] = DEVICE_NAMES[toDevice] || "";
            line["from"] = "";
            line["to"] = toDevice;
            line["verb"] = cols[2] || "";
            line["function"] = cols[3] || "";
            line["zone"] = cols[4] || "";
        }

        try {
            let jsonValidStr = payloadSection
                .replace(/'/g, '"')
                .replace(/True/g, 'true')
                .replace(/False/g, 'false')
                .replace(/None/g, 'null');
            line["payload"] = JSON.parse(jsonValidStr);
        } catch (e) {
            line["payload"] = payloadSection;
        }

    } else {
        // Use pipe positions directly so any | inside a message body is preserved.
        const firstPipe = text.indexOf("|");
        const timestamp = firstPipe !== -1 ? text.substring(0, firstPipe).trim() : text;
        const secondPipe = firstPipe !== -1 ? text.indexOf("|", firstPipe + 1) : -1;
        const messageBody = secondPipe !== -1 ? text.substring(secondPipe + 1).trim() : "";

        line["time"] = timestamp;
        line["sourceType"] = "";
        line["from"] = "";
        line["to"] = "";
        line["verb"] = "";
        line["zone"] = "";
        line["payload"] = "";

        if (messageBody.startsWith("MQTT message received:")) {
            const jsonPart = messageBody.replace("MQTT message received:", "").trim();
            line["from"] = "MQTT";
            line["function"] = "mqtt_in";
            try {
                let jsonValidStr = jsonPart
                    .replace(/'/g, '"')
                    .replace(/True/g, 'true')
                    .replace(/False/g, 'false')
                    .replace(/None/g, 'null');
                line["payload"] = JSON.parse(jsonValidStr);
            } catch (e) {
                line["payload"] = jsonPart;
            }
            line.style = { "color": "#7ec8e3" };

        } else if (messageBody.startsWith("Command Send Status:")) {
            const match = messageBody.match(/Command Send Status:\s*(\w+)\s*\(command=([^)]+)\)/);
            line["from"] = "MQTT";
            line["function"] = "cmd_status";
            if (match) {
                line["payload"] = { status: match[1], command: match[2] };
                line.style = match[1] === "Successful"
                    ? { "color": "#90ee90" }
                    : { "color": "#ffd700" };
            } else {
                line["payload"] = messageBody;
                line.style = { "color": "#ffd700" };
            }

        } else {
            line["function"] = "System";
            let msg = messageBody.replace(/^"/, '').replace(/"$/, '');
            line["payload"] = msg;
            line.style = { "color": "#a8a8a8", "font-style": "italic" };
        }
    }

    return line;
}
